{
  "includeCoAuthoredBy": false,
  "attribution": {
    "commit": "",
    "pr": ""
  },
  "autoMemoryEnabled": false,
  "claudeMdExcludes": [
    "/home/alex-example/CLAUDE.md",
    "/home/alex-example/CLAUDE.local.md",
    "/home/alex-example/.claude/CLAUDE.md",
    "/home/CLAUDE.md",
    "/home/CLAUDE.local.md",
    "/home/.claude/CLAUDE.md",
    "/CLAUDE.md",
    "/CLAUDE.local.md",
    "/.claude/CLAUDE.md"
  ],
  "sandbox": {
    "enabled": true,
    "failIfUnavailable": true,
    "allowUnsandboxedCommands": false,
    "autoAllowBashIfSandboxed": true,
    "network": {
      "allowedDomains": [
        "registry.example.com"
      ],
      "strictAllowlist": true
    },
    "filesystem": {
      "allowWrite": [
        "//home/alex-example/example-repository/.example-worktrees/hatch/J1",
        "//home/alex-example/example-repository/.example-cache"
      ],
      "denyWrite": [
        "//home/alex-example/example-repository/.example-data",
        "//home/alex-example/example-repository/.example-worktrees/ticket-7/.claude"
      ],
      "denyRead": [
        "//home/alex-example/.ssh"
      ]
    }
  },
  "permissions": {
    "allow": [
      "Read",
      "Agent",
      "Edit(//home/alex-example/example-repository/.example-worktrees/ticket-7/**)",
      "Write(//home/alex-example/example-repository/.example-worktrees/ticket-7/**)",
      "Bash(bun run verify *)",
      "Bash(git commit *)",
      "WebFetch(domain:registry.example.com)"
    ],
    "deny": [
      "Edit(//home/alex-example/example-repository/.example-data)",
      "Edit(//home/alex-example/example-repository/.example-data/**)",
      "Write(//home/alex-example/example-repository/.example-data)",
      "Write(//home/alex-example/example-repository/.example-data/**)",
      "Edit(//home/alex-example/example-repository/.example-worktrees/ticket-7/.claude)",
      "Edit(//home/alex-example/example-repository/.example-worktrees/ticket-7/.claude/**)",
      "Write(//home/alex-example/example-repository/.example-worktrees/ticket-7/.claude)",
      "Write(//home/alex-example/example-repository/.example-worktrees/ticket-7/.claude/**)",
      "Read(//home/alex-example/.ssh)",
      "Read(//home/alex-example/.ssh/**)",
      "Bash(git push *)",
      "Bash(git rebase *)"
    ]
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "/home/alex-example/.bun/bin/example-program hook bash-domains --allow 'registry.example.com,*.docs.example.org'"
          }
        ]
      },
      {
        "matcher": "WebFetch",
        "hooks": [
          {
            "type": "command",
            "command": "/home/alex-example/.bun/bin/example-program hook bash-domains --allow 'registry.example.com,*.docs.example.org'"
          }
        ]
      }
    ]
  }
}

